export default "/* Base Button Styles */\r\nbutton {\r\n  border: 2px solid transparent;\r\n  padding: 10px 20px;\r\n  border-radius: 5px; /* Adjusted for a more standard look */\r\n  cursor: pointer;\r\n  font-size: 1rem; /* Adjusted for a more standard size */\r\n  transition: all 0.3s ease, color 0.3s ease, box-shadow 0.3s ease;\r\n  display: inline-block; /* For proper alignment */\r\n  text-align: center;\r\n  vertical-align: middle;\r\n  user-select: none; /* Prevent text selection */\r\n  -webkit-user-select: none;\r\n  touch-action: manipulation; /* Optimize for touch devices */\r\n  width: 100%;\r\n  font-weight: 700;\r\n  background-color: var(--primary);\r\n  color: var(--white);\r\n  border: 2px solid var(--primary);\r\n}\r\n\r\n/* Button Hover and Focus States */\r\nbutton:hover,\r\nbutton:focus {\r\n  /* color: var(--primary) !important;\r\n  background-color: var(--bg-primary) !important;\r\n  border: 2px solid var(--primary) !important; */\r\n  text-decoration: none;\r\n}\r\n\r\n/* Button Active State */\r\nbutton:active {\r\n  background-color: var(--white); /* Even darker for active state */\r\n  color: var(--primary);\r\n  box-shadow: inset 0 3px 5px rgba(0, 0, 0, 0.125); /* Inner shadow for a \"pressed\" effect */\r\n}\r\n\r\n/* Disabled Button State */\r\nbutton:disabled {\r\n  background-color: var(--gray);\r\n  color: var(--gray-dark);\r\n  cursor: not-allowed;\r\n  opacity: 0.65;\r\n}\r\n\r\n/* Button Variants */\r\n.button-primary {\r\n  background-color: var(--primary);\r\n}\r\n.button-secondary {\r\n  background-color: var(--secondary);\r\n}\r\n.button-success {\r\n  background-color: var(--success);\r\n}\r\n.button-danger {\r\n  background-color: var(--danger);\r\n}\r\n.button-warning {\r\n  background-color: var(--warning);\r\n}\r\n.button-info {\r\n  background-color: var(--info);\r\n}\r\n.button-light {\r\n  background-color: var(--light);\r\n  color: var(--dark);\r\n}\r\n.button-dark {\r\n  background-color: var(--dark);\r\n}\r\n\r\n/* Button Sizes */\r\n.button-sm {\r\n  padding: 5px 10px;\r\n  font-size: 0.875rem;\r\n}\r\n.button-lg {\r\n  padding: 15px 30px;\r\n  font-size: 1.25rem;\r\n}\r\n.button-default {\r\n  padding: 10px 20px;\r\n  font-size: 1rem;\r\n}\r\n\r\n/* Utility: Clearfix */\r\n.clearfix::after {\r\n  content: \"\";\r\n  display: table;\r\n  clear: both;\r\n}\r\n\r\n/* Utility: Disabled opacity for button groups or link buttons */\r\n.disabled {\r\n  opacity: 0.65;\r\n  pointer-events: none;\r\n}\r\n\r\n.button-transparent {\r\n  background-color: transparent !important;\r\n  color: var(--white);\r\n}\r\n\r\n.button-transparent:hover {\r\n  transform: scale(1.5);\r\n  background-color: transparent !important;\r\n}\r\n\r\n.button-group {\r\n  display: flex;\r\n  gap: 10px;\r\n}\r\n";